package com.corecs.solid.controller;import com.corecs.solid.dto.AnalyzeRequest;import com.corecs.solid.analyzer.SolidAnalyzer;import com.corecs.solid.model.AnalysisResult;import com.corecs.solid.parser.JavaAstParser;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/solid") public class SolidController{private final JavaAstParser parser;private final SolidAnalyzer analyzer;public SolidController(JavaAstParser p,SolidAnalyzer a){parser=p;analyzer=a;}@PostMapping("/analyze")public AnalysisResult analyze(@Valid @RequestBody AnalyzeRequest r){return analyzer.analyze(parser.parse(r.code()));}}
